//! Trustless OSS notification collection. Generated by scripts/export-emails.ts.
//! Drop-in replacement: preserves EmailTemplate and email_template_for signatures.
//! All recipient/GitHub content is escaped. No additional Rust dependencies.
//! Optional data fields: name, repository, issue, amount, asset (or currency).
//! Existing notification data is never parsed from free-form body text.
//! Publish this studio (or host its supplied logo on your permanent asset CDN)
//! before sending: email images must be reachable over public HTTPS.
use crate::modules::notification::kinds::Kind;
use serde_json::Value;

pub struct EmailTemplate {
    pub subject: String,
    pub html: String,
}

fn escape_html(input: &str) -> String {
    input
        .replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
        .replace('\'', "&#39;")
}
fn value(data: &Value, key: &str, fallback: &str) -> String {
    match data.get(key) {
        Some(Value::String(s)) if !s.trim().is_empty() => s.clone(),
        Some(Value::Number(n)) => n.to_string(),
        _ => fallback.to_string(),
    }
}
fn safe_base(input: &str) -> String {
    let input = input.trim_end_matches('/');
    let authority = input
        .strip_prefix("https://")
        .and_then(|rest| rest.split('/').next())
        .unwrap_or("");
    if !authority.is_empty()
        && !input.chars().any(|c| {
            c.is_control() || c.is_whitespace() || matches!(c, '"' | '\'' | '<' | '>' | '\\')
        })
        && !authority.contains('@')
        && !authority.contains('?')
        && !authority.contains('#')
        && !input.contains('?')
        && !input.contains('#')
    {
        input.to_string()
    } else {
        "https://www.trustless-oss.xyz".to_string()
    }
}
pub fn email_template_for(
    kind: Kind,
    title: &str,
    body: &str,
    data: &Value,
    app_url: &str,
) -> EmailTemplate {
    let (source, subject) = match kind {
        Kind::BountyAssigned => (BOUNTYASSIGNED, "Bounty assigned"),
        Kind::BountyUnassigned => (BOUNTYUNASSIGNED, "Bounty unassigned"),
        Kind::BountyLocked => (BOUNTYLOCKED, "Bounty locked"),
        Kind::BountyCancelled => (BOUNTYCANCELLED, "Bounty cancelled"),
        Kind::BountyRejected => (BOUNTYREJECTED, "Bounty rejected"),
        Kind::AmountUpdated => (AMOUNTUPDATED, "Reward updated"),
        Kind::AmountMissing => (AMOUNTMISSING, "Reward pending"),
        Kind::WalletRequired => (WALLETREQUIRED, "Wallet required"),
        Kind::PayoutReleased => (PAYOUTRELEASED, "Payout released"),
        Kind::PayoutBlocked => (PAYOUTBLOCKED, "Payout blocked"),
        Kind::InsufficientFunds => (INSUFFICIENTFUNDS, "Insufficient funds"),
        Kind::EscrowFunded => (ESCROWFUNDED, "Escrow funded"),
        Kind::EscrowRefunded => (ESCROWREFUNDED, "Escrow refunded"),
    };
    let base = safe_base(app_url);
    let name = value(data, "name", "there");
    let repo = value(data, "repository", "See repository in your account");
    let issue = value(data, "issue", "—");
    let amount = value(data, "amount", "Not provided");
    let asset = value(data, "asset", &value(data, "currency", ""));
    let replacements = [
        ("TOSS_NAME_TOKEN", escape_html(&name)),
        ("TOSS_REPO_TOKEN", escape_html(&repo)),
        ("TOSS_ISSUE_TOKEN", escape_html(&issue)),
        ("TOSS_AMOUNT_TOKEN", escape_html(&amount)),
        ("TOSS_ASSET_TOKEN", escape_html(&asset)),
        ("TOSS_TITLE_TOKEN", escape_html(title)),
        ("TOSS_BODY_TOKEN", escape_html(body).replace('\n', "<br>")),
    ];
    // Single-pass substitution: user content is never processed as another token.
    let original = source.replace("https://www.trustless-oss.xyz", &escape_html(&base));
    let mut html = String::with_capacity(original.len());
    let mut rest = original.as_str();
    while !rest.is_empty() {
        if let Some((position, token, replacement)) = replacements
            .iter()
            .filter_map(|(token, replacement)| rest.find(token).map(|p| (p, *token, replacement)))
            .min_by_key(|(position, _, _)| *position)
        {
            html.push_str(&rest[..position]);
            html.push_str(replacement);
            rest = &rest[position + token.len()..];
        } else {
            html.push_str(rest);
            break;
        }
    }
    let title = title.replace(['\r', '\n'], " ");
    let subject = if title.trim().is_empty() {
        subject.to_string()
    } else {
        format!("{} · {}", subject, title)
    };
    EmailTemplate { subject, html }
}

